OMNI=[['拉丁 omnis 全部、每一个','其组合形式 omni- 在英语中表达所有方向、渠道、能力等']]
OMP=OMNI+[['拉丁 praesens 在场 + omni- → 中世纪拉丁 omnipraesens','处处都在的']]
VISC=[['拉丁 viscus 内脏，复数 viscera','内在器官，也可借来形容人内心深处']]
VISCERAL=VISC+[['中世纪拉丁 visceralis → 法语 viscéral／英语 visceral','内在的；英语的情感义与内脏义并非简单的先实后虚顺序']]
EVISC=VISC+[['拉丁 e-/ex- 出 + viscera → eviscerare → evisceratus','取出内脏'],['英语 eviscerate','也用于抽空核心、严重削弱或猛烈批评的比喻']]
PALP=[['拉丁 palpare 轻触、抚摸','具体更远来源不确定，不强接英语 feel']]
PALPABLE=PALP+[['晚期拉丁 palpabilis → 法语 palpable／英语 palpable','可触到的；也指明显得仿佛可以触到']]
PALPATION=PALP+[['拉丁 palpatio → 法语 palpation → 英语 palpation','触摸检查；英语名词早于现代动词 palpate']]
LEN=[['拉丁 lenis 柔和的 → lenire 使柔和、缓和','不那么硬、不那么严厉'],['拉丁 leniens，词干 lenient- → 法语 lenient → 英语 lenient','由舒缓发展到处理、处罚宽和']]
TERG=[['拉丁 tergere 擦、擦净','擦掉多余东西，留下干净表面']]
TERSE=TERG+[['拉丁过去分词 tersus → 法语 ters／英语 terse','擦净、整洁；后来形容文字精练，再带简短冷硬的语感']]
TENU=[['拉丁 tenuis 细、薄、弱','由此有动词 tenuare 使变薄；薄弱结构也成为不牢靠关系的比喻']]
TENUOUS=TENU+[['拉丁 tenuis + 英语形容词后缀 -ous → tenuous','细薄、微弱；现代常说关系、证据或地位不牢靠']]
ATTEN=TENU+[['拉丁 ad- 向着 + tenuare → attenuare','使变薄、减少；ad- 同化成 at-']]
ATTENUATE=ATTEN+[['拉丁 attenuatus → 英语 attenuate','减弱、衰减；有较早相关英语词形']]
EXTEN=TENU+[['拉丁 ex- 向外、加强 + tenuare → extenuare → extenuatus','使变薄、降低程度'],['英语 extenuate','减轻；尤其使错误显得没那么应受责备']]
CYN=[['希腊 kyon，词干 kyn-，狗 → kynikos 像狗的、犬儒的','为何用狗命名该学派，有生活方式、绰号或地点等不同说法'],['拉丁 cynicus／法语 cynique → 英语 cynic','古代犬儒学派成员；后来另发展出现代怀疑人性动机的用法']]
STAGN=[['拉丁 stagnum 静水、池 → stagnare 形成静水、不流动','水不再流动，成为发展停住的画面']]
STAGNATE=STAGN+[['拉丁 stagnatus → 英语 stagnate','停止流动；后来指不再发展']]
STILLA=[['拉丁 stilla 一滴 → stillare 滴下','一滴一滴的液体，不是日耳曼语安静的 still']]
DIST=STILLA+[['拉丁 dis- 分开 + stillare → distillare','滴下、逐滴流下']]
DISTILL=DIST+[['古法语 distiller → 英语 distill／distil','蒸馏；后来也说提炼信息中的精华']]
OSC=[['拉丁 oscillum 摆动物 → oscillare 摆动','常联系悬挂随风摇动的小面具、os 嘴或脸；这种联系是通常解释，不作无争议事实']]
OSCILLATION=OSC+[['拉丁 oscillatio → 法语 oscillation／英语 oscillation','摆动、振荡；英语名词早于 oscillate']]
OSCILLATE=OSC+[['英语 oscillation 反构／拉丁 oscillatus 借入 → oscillate','词典保留两种直接来源解释；都接拉丁摆动词族']]
