print('st51 working',len(W))
W += [
E('tenuous','/ˈtenjuəs/','薄弱的；牵强的；不牢靠的','像一根太细的线，勉强连着，稍有变化就可能断。','英语用拉丁 tenuis 细、薄配 -ous 形成形容词；现代写法不是把某个现成英语词 tenu 去掉词尾。',TENUOUS,'a tenuous connection 是联系很薄弱，a tenuous claim 是依据不足。也能说 tenuous control：暂时还控制得住，却很不稳。','a tenuous link；a tenuous connection；a tenuous hold on power。','weak 范围宽，tenuous 常特别像联系细、基础薄。tenacious 是抓得牢、不放弃，虽然拼写接近，现代语感几乎相反。',('The evidence showed only a tenuous link between the two events.','证据只显示两件事之间有很薄弱的联系。'),('The government retained a tenuous hold on power.','政府仍勉强维持着不稳固的权力。'),sources=['https://www.etymonline.com/word/tenuous','https://www.oxfordlearnersdictionaries.com/definition/english/tenuous']),
E('tenuously','/ˈtenjuəsli/','薄弱地；勉强地；不牢靠地','两个东西之间只靠很细的一条线维持着。','tenuous + -ly，现代英语副词，底层是拉丁细薄的概念。',TENUOUS+[['英语 tenuous + -ly → tenuously','以薄弱、不牢靠的方式']],'tenuously connected 常说联系牵强；tenuously held 可以说地位或看法不稳。它不等于完全没有关系，而是关系不足以让人放心。','tenuously linked；tenuously connected；tenuously held beliefs。','loosely 可以说联系松散却仍合理；tenuously 常进一步暗示基础太薄、可能站不住。barely 只说刚够程度，不一定涉及联系。',('The conclusion was only tenuously connected to the evidence.','结论与证据之间的联系十分牵强。'),('The two villages were tenuously linked by a narrow mountain road.','两个村庄只靠一条狭窄山路勉强连通。'),sources=['https://www.etymonline.com/word/tenuous','https://www.oxfordlearnersdictionaries.com/definition/english/tenuously']),
E('attenuate','常用动词 /əˈtenjueɪt/；较专门形容词 /əˈtenjuət/','减弱；使衰减；使变细','把强度削薄一层：声音小一点、信号弱一点，或实物变细。','拉丁 ad- + tenuare → attenuare，使变薄；由过去分词 attenuatus 进入英语。较早英语已有相关形容词形式，不能把所有词性都排成现代动词先行。',ATTENUATE,'attenuate a signal 是降低信号强度，不等于把信号彻底删除。attenuate the impact 是削弱影响。专业形容词 attenuate 可形容细长、逐渐变尖的形状，读法与动词尾音不同。','attenuate a signal；attenuate sound；attenuate the effect of something。','reduce 是普通减少，attenuate 常用于强度或作用逐渐减弱。amplify 是放大，与信号语境中的 attenuate 相对。',('The thick curtain attenuated the sound from the street.','厚窗帘减弱了街上传来的声音。'),('Distance can attenuate the strength of a wireless signal.','距离会削弱无线信号的强度。'),sources=['https://www.etymonline.com/word/attenuate','https://www.merriam-webster.com/dictionary/attenuate']),
E('attenuation','/əˌtenjuˈeɪʃən/','衰减；减弱；变细','不是盯着东西本身，而是量它在传播或处理后弱了多少。','接拉丁 attenuatio，来自 attenuare 使变薄。英语名词的记录早于现代动词 attenuate；现代能按动词与 -ion 联系，但那不是唯一历史解释。',ATTEN+[['拉丁 attenuatio → 英语 attenuation','变薄、减少；后来用于声音、光、信号等的衰减']],'signal attenuation 是信号衰减，sound attenuation 是声音减弱。它可以是传播中的损失，也可以是设计者有意降低强度。','signal attenuation；sound attenuation；measure attenuation。','distortion 是形状或波形被改变，attenuation 重点是强度下降；信号可以变弱而大致保持原来的形状。',('The engineers measured signal attenuation along the cable.','工程师测量了信号沿电缆传输时的衰减。'),('The panel provides sound attenuation between the two rooms.','这块板能减弱两个房间之间传递的声音。'),sources=['https://www.etymonline.com/word/attenuation','https://www.oxfordlearnersdictionaries.com/definition/english/attenuation']),
E('attenuated','/əˈtenjueɪtɪd/','减弱的；变细长的；衰减后的','力量已被削弱，或形状被拉成细长的样子。','attenuate + -ed，是英语过去式、过去分词，也可作形容词；-ed 在 /t/ 后读 /ɪd/。',ATTENUATE+[['英语 attenuate + -ed → attenuated','已变弱、已变细或相关状态']],'an attenuated signal 是变弱的信号；attenuated figures 在艺术描述中可说细长的人物形象。医学里的 attenuated 也用于减毒，但不是指病原体已经被杀死。','an attenuated signal；attenuated forms；an attenuated effect。','weak 是弱，attenuated 常带原有强度被降低的过程。elongated 只说拉长，attenuated 还突出细或弱。',('Only an attenuated signal reached the receiver.','只有减弱后的信号到达接收器。'),('The sculpture’s attenuated limbs gave it a fragile appearance.','雕塑细长的四肢让它显得脆弱。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/attenuated','https://www.merriam-webster.com/dictionary/attenuate']),
E('extenuate','/ɪkˈstenjueɪt/','减轻；使过错显得情有可原','给出背景，让一件错事看起来没那么应受责备；不是证明它根本没发生。','拉丁 ex- + tenuare → extenuare，变薄、减少；由 extenuatus 借入英语。由减小程度转到减轻过错或责任的严重性。',EXTEN,'extenuate a mistake 是减轻错误的可责程度，通常很正式。这个词今天更容易在 extenuating circumstances 情有可原的情况里见到。','extenuate a fault；extenuate the seriousness of an offence；nothing can extenuate。','excuse 有时近似原谅或免责，extenuate 可以只是部分减轻。aggravate 是加重；不要因拼写像 extend 就把 extenuate 当作延长。',('The lack of training may extenuate the mistake, but it does not erase it.','缺乏培训可能让这次错误情有可原，但不能抹去错误本身。'),('She offered no explanation that could extenuate her conduct.','她没有提出任何能减轻其行为过错的解释。'),sources=['https://www.etymonline.com/word/extenuate','https://www.merriam-webster.com/dictionary/extenuate']),
E('extenuating','/ɪkˈstenjueɪtɪŋ/','情有可原的；可减轻责任的','有额外情况，使人觉得不该按最严厉的标准责怪当事人。','extenuate + -ing，原是使程度减轻的动词形式，常固定作 extenuating circumstances 的形容词。',EXTEN+[['英语 extenuate + -ing → extenuating','有助减轻过错、责备程度的']],'最值得记住的整块是 extenuating circumstances。它可以用于学校迟交、工作失误等，并不限于法庭；是否被接受要看具体规则。','extenuating circumstances；take extenuating circumstances into account。','mitigating circumstances 很接近。extenuating 不是普通 difficult：情况困难还须与失误相关，才可能构成减轻责备的理由。',('The school considered her extenuating circumstances before applying the penalty.','学校在作出处罚前考虑了她情有可原的特殊情况。'),('He explained that a family emergency was an extenuating circumstance.','他解释说，家中的突发急事是一个情有可原的情况。'),sources=['https://www.etymonline.com/word/extenuate','https://www.oxfordlearnersdictionaries.com/definition/english/extenuating']),
E('cynic','/ˈsɪnɪk/','不相信别人真诚的人；犬儒学派成员','别人说自己出于善意，他先想：恐怕是为了钱、名声或别的好处。','经拉丁 cynicus、法语 cynique 接希腊 kynikos，联系 kyon 狗。学派为何被这样称呼存在不同解释，涉及生活方式、绰号或 Cynosarges 地点，不能只讲一个确定的狗故事。',CYN,'现代 a cynic 主要怀疑人的动机，不是任何提出质疑的人。历史里的 a Cynic 则说古代犬儒学派成员，不能拿现代冷嘲热讽的刻板印象替代整个学派。','a hardened cynic；become a cynic；a cynic about politics。','skeptic 怀疑一个主张是否有证据；cynic 更倾向先怀疑人是否真诚。pessimist 认为结果可能不好，也不一定怀疑动机。',('A cynic might say the donation was mainly about publicity.','一个惯于怀疑动机的人也许会说，这次捐款主要是为了宣传。'),('The course compares the ancient Cynics with the Stoics.','课程比较了古代犬儒学派与斯多葛学派。'),sources=['https://www.etymonline.com/word/cynic','https://iep.utm.edu/cynics/','https://www.oxfordlearnersdictionaries.com/definition/english/cynic']),
E('cynical','/ˈsɪnɪkəl/','认为别人动机不纯的；冷嘲的；只顾自身利益的','要么觉得别人嘴上说得好听，背后都是算盘；要么自己就明知如此，仍为了利益去做。','cynic + -al，早期指像犬儒学派的，后来形成今天怀疑真诚、轻视道德动机的意义。不能把现代所有用法都当成古代学说的准确概括。',CYN+[['英语 cynic + -al → cynical','从学派相关，扩展到怀疑动机或冷漠逐利的态度']],'cynical about promises 是不信承诺背后的真心；a cynical attempt to gain votes 可以说只是盘算选票、毫无真诚的举动。后一种不只是表示悲观。','be cynical about；a cynical remark；a cynical attempt to gain support。','skeptical 往往先要证据，cynical 往往先觉得动机不纯。sarcastic 是说话讽刺的方式，不一定来自犬儒态度。',('She became cynical about the company’s promises.','她开始觉得公司的承诺都不真诚。'),('The gesture was dismissed as a cynical attempt to win support.','人们认为这个姿态只是为拉取支持而作的算计，因而不予认可。'),sources=['https://www.etymonline.com/word/cynical','https://www.oxfordlearnersdictionaries.com/definition/english/cynical']),
E('cynically','/ˈsɪnɪkli/','怀疑动机地；冷嘲地；不顾原则地','说话时默认别人没安好心，或行动时只盘算自己的好处。','cynical + -ly；现代常省略中间弱元音，读 /ˈsɪnɪkli/。来源经过古代犬儒名称，但现代语气已有明显变化。',CYN+[['英语 cynic → cynical → cynically','由态度形容词成为描述判断或行为方式的副词']],'comment cynically 是带着不信真诚的口吻评论；cynically exploit a situation 是明知不妥仍为获利利用局面。不要把这两种都只翻成讽刺地。','remark cynically；view something cynically；cynically exploit。','sarcastically 主要说话带讽刺，cynically 还可直接描述利用他人的行为。pessimistically 说预期不好，不一定涉及利益算计。',('“How generous—just before the election,” he remarked cynically.','“真慷慨啊，偏偏就在选举前。”他挖苦道。'),('The company cynically exploited customers’ fear of losing their data.','公司只顾自身利益，利用了顾客担心丢失数据的恐惧。'),sources=['https://www.etymonline.com/word/cynical','https://www.oxfordlearnersdictionaries.com/definition/english/cynically']),
E('cynicism','/ˈsɪnɪsɪzəm/','对他人动机的普遍怀疑；犬儒主义','总认为漂亮话后面藏着私利，这种习惯性的看法就是现代常说的 cynicism。','cynic + -ism，原来指犬儒学派思想，后来成为现代怀疑真诚、冷嘲世事这一态度的名称。历史学派与现代贬义不能完全重合。',CYN+[['英语 cynic + -ism → Cynicism／cynicism','古代哲学名称，后来另发展出现代态度义']],'growing cynicism about politics 是越来越不信政治人物的真心。它可以来自失望，但这个词不保证怀疑一定合理，也不等于成熟或聪明。','public cynicism；cynicism about politics；a sense of cynicism。','skepticism 可以是有方法地求证；cynicism 更容易预设动机不纯。ancient Cynicism 在哲学史中另有完整思想背景。',('Repeated scandals increased public cynicism about the institution.','接连的丑闻加深了公众对这个机构动机的怀疑。'),('She tried to discuss the problem without falling into cynicism.','她试着讨论这个问题，而不陷入凡事都怀疑动机的态度。'),sources=['https://www.etymonline.com/word/cynicism','https://www.oxfordlearnersdictionaries.com/definition/english/cynicism','https://iep.utm.edu/cynics/']),
E('stagnant','/ˈstæɡnənt/','停滞的；不流动的；缺乏生气的','像一池不流动的水，留在那里，没有新的流入和推进。','法语 stagnant 接拉丁 stagnans，是 stagnare 不流动的现在分词；往前是 stagnum 静水、池。不是英语 stagnate 加形容词后缀的唯一历史。',STAGN+[['拉丁 stagnans → 法语 stagnant → 英语 stagnant','静止不流动；也比喻发展迟滞']],'stagnant water 是不流动的水；stagnant wages 是工资长期不涨。词义是不流动或不发展，不要求每次都已经腐臭。','stagnant water；stagnant wages；a stagnant economy。','stable 可以正面地说稳定；stagnant 往往负面地说缺少应有的发展。stationary 只说位置不移动，未必有停滞感。',('Stagnant water had collected in the old ditch.','旧沟里积了一些不流动的水。'),('Workers were frustrated by years of stagnant wages.','工资多年不涨，让员工感到沮丧。'),sources=['https://www.etymonline.com/word/stagnant','https://www.oxfordlearnersdictionaries.com/definition/english/stagnant']),
E('stagnate','/ˈstæɡneɪt/','停滞；不再发展；不流动','原本该继续前进，却在原地停住，慢慢失去活力。','接拉丁 stagnatus，来自 stagnare 不流动。与 stagnant 共用拉丁来源，英语中一个说过程，一个说状态。',STAGNATE,'a career stagnates 是职业发展停住；sales stagnate 是销售不再增长。通常作不及物动词：something stagnates，而不是随意把人或物当直接宾语。','sales stagnate；a career stagnates；allow something to stagnate。','decline 是下降，stagnate 可以停在同一水平而没有下降。pause 可以短暂且有意，stagnate 常暗示停得过久。',('Her career began to stagnate after several years in the same role.','在同一岗位待了几年后，她的职业发展开始停滞。'),('Without new investment, the business may stagnate.','如果没有新的投入，业务可能停滞不前。'),sources=['https://www.etymonline.com/word/stagnate','https://www.oxfordlearnersdictionaries.com/definition/english/stagnate']),
E('stagnation','/stæɡˈneɪʃən/','停滞；萧条；不流动','把长时间没有推进这一状态当成一个整体问题来看。','英语 stagnate 配 -ion 的动作、状态名词，底层是拉丁 stagnare 静水不流。现代常用于经济、职业或机构发展。',STAGNATE+[['英语 stagnate → stagnation','停止流动，进而指长期缺少发展']],'economic stagnation 是经济增长长期乏力；creative stagnation 是创作上没有新变化。通常不可数，不把一次小停顿就夸成长期停滞。','economic stagnation；years of stagnation；break out of stagnation。','recession 通常说经济活动收缩，stagnation 更强调不增长或缺少动力。stability 可以是理想状态，stagnation 常带不满。',('The region faced years of economic stagnation.','这个地区经历了多年的经济停滞。'),('A change of leadership helped the organisation escape stagnation.','领导层的变动帮助这个组织走出了停滞。'),sources=['https://www.etymonline.com/word/stagnation','https://www.oxfordlearnersdictionaries.com/definition/english/stagnation']),
E('stagflation','/stæɡˈfleɪʃən/','滞胀','经济没什么增长动力，物价却还在涨，常伴随就业状况不佳。','现代英语混成词：取 stagnation 的 stag- 与 inflation 的 -flation 拼合。名称在二十世纪六十年代流行，不是从古代拉丁语整词借来的。',STAGNATE+[['英语 stagnation 停滞 + inflation 通胀 → stagflation','两种问题同时出现，因此把两个词压成一个名称']],'理解它只需同时看两条线：经济活动疲弱，价格仍上涨。它不要求每一个经济指标绝对不动，也不只是单独的通胀。','a period of stagflation；the risk of stagflation；stagflation in the 1970s。','inflation 单说总体物价上涨；stagnation 单说发展乏力。stagflation 则把疲弱增长与通胀放在同一时期讨论。',('The article explained how weak growth and rising prices can produce stagflation.','文章解释了增长乏力与物价上涨怎样共同形成滞胀。'),('The seminar compared stagflation with ordinary periods of inflation.','研讨会比较了滞胀与一般通胀时期的差别。'),sources=['https://www.etymonline.com/word/stagflation','https://www.oxfordlearnersdictionaries.com/definition/english/stagflation','https://www.clevelandfed.org/collections/infographics/2025/infogr-20251117-stagflation']),
]
